import 'dart:io';import 'package:html/parser.dart';void main(){final d=parse(File('tool/fixtures/flv_new_home.html').readAsStringSync());for(final a in d.querySelectorAll('a[href*="/anime/"]').where((a)=>a.querySelector('img')!=null).take(6)){stdout.writeln('${a.parent?.classes} | ${a.classes} | ${a.outerHtml.substring(0,250)}');}for(final a in d.querySelectorAll('a[href]').where((a)=>a.text.trim()=='Directorio Anime').take(1)){stdout.writeln('DIRECTORY=${a.attributes["href"]}');}}
